&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Fluency in English is required; Proficiency in French or Portuguese is highly desirable&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:278}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
